const fs=require('fs'),zlib=require('zlib');
function decode(file){
  const b=fs.readFileSync(file);
  let off=8, w=0,h=0,bd=0,ct=0, idat=[];
  while(off<b.length){
    const len=b.readUInt32BE(off); const type=b.toString('ascii',off+4,off+8);
    const data=b.slice(off+8,off+8+len);
    if(type==='IHDR'){w=data.readUInt32BE(0);h=data.readUInt32BE(4);bd=data[8];ct=data[9];}
    if(type==='IDAT') idat.push(data);
    if(type==='IEND') break;
    off+=12+len;
  }
  const raw=zlib.inflateSync(Buffer.concat(idat));
  const ch = ct===6?4:ct===2?3:ct===0?1:ct===4?2:0;
  const bpp=ch*(bd/8);
  const stride=w*bpp;
  const out=Buffer.alloc(h*stride);
  let pos=0;
  for(let y=0;y<h;y++){
    const ft=raw[pos++];
    const line=raw.slice(pos,pos+stride); pos+=stride;
    const prev = y>0? out.slice((y-1)*stride, y*stride): Buffer.alloc(stride);
    const cur=out.slice(y*stride,(y+1)*stride);
    for(let x=0;x<stride;x++){
      const a = x>=bpp? cur[x-bpp]:0;
      const bb = prev[x];
      const c = x>=bpp? prev[x-bpp]:0;
      let v=line[x];
      if(ft===1) v+=a; else if(ft===2) v+=bb; else if(ft===3) v+=Math.floor((a+bb)/2);
      else if(ft===4){const p=a+bb-c;const pa=Math.abs(p-a),pb=Math.abs(p-bb),pc=Math.abs(p-c);v+= (pa<=pb&&pa<=pc)?a:(pb<=pc?bb:c);}
      cur[x]=v&255;
    }
  }
  return {w,h,ch,bpp,stride,data:out};
}
module.exports={decode};
EOF
