const fs=require('fs'),zlib=require('zlib');
const {decode}=require('./_png.js');
function crc32(buf){let c,t=[];for(let n=0;n<256;n++){c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}
let crc=0xFFFFFFFF;for(let i=0;i<buf.length;i++)crc=t[(crc^buf[i])&255]^(crc>>>8);return (crc^0xFFFFFFFF)>>>0;}
function chunk(type,data){const len=Buffer.alloc(4);len.writeUInt32BE(data.length);const td=Buffer.concat([Buffer.from(type,'ascii'),data]);const crc=Buffer.alloc(4);crc.writeUInt32BE(crc32(td));return Buffer.concat([len,td,crc]);}
function encode(w,h,rgb){const stride=w*3;const raw=Buffer.alloc(h*(stride+1));for(let y=0;y<h;y++){raw[y*(stride+1)]=0;rgb.copy(raw,y*(stride+1)+1,y*stride,(y+1)*stride);}const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(w,0);ihdr.writeUInt32BE(h,4);ihdr[8]=8;ihdr[9]=2;return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',ihdr),chunk('IDAT',zlib.deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);}
const img=decode(process.argv[2]);
const x0=+process.argv[3],y0=+process.argv[4],x1=+process.argv[5],y1=+process.argv[6];
const sc=+(process.argv[7]||1);
const cw=x1-x0, chh=y1-y0;
const ow=Math.floor(cw/sc), oh=Math.floor(chh/sc);
const out=Buffer.alloc(ow*oh*3);
for(let y=0;y<oh;y++)for(let x=0;x<ow;x++){
  const sx=x0+Math.floor(x*sc), sy=y0+Math.floor(y*sc);
  const i=sy*img.stride+sx*img.ch;
  out[(y*ow+x)*3]=img.data[i];out[(y*ow+x)*3+1]=img.data[i+1];out[(y*ow+x)*3+2]=img.data[i+2];
}
fs.writeFileSync(process.argv[8],encode(ow,oh,out));
console.log('wrote',process.argv[8],ow+'x'+oh);
